// Procedural Textures via Canvas
function createAsphaltTexture() {
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 1024;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#22252c';
  ctx.fillRect(0, 0, 1024, 1024);

  // Fine grit noise
  for (let i = 0; i < 60000; i++) {
    const x = Math.floor(deterministicRandom() * 1024);
    const y = Math.floor(deterministicRandom() * 1024);
    const shade = Math.floor(25 + deterministicRandom() * 35);
    ctx.fillStyle = `rgb(${shade},${shade},${shade})`;
    ctx.fillRect(x, y, 1, 1);
  }
  // Pebble aggregates
  for (let i = 0; i < 3000; i++) {
    const x = Math.floor(deterministicRandom() * 1024);
    const y = Math.floor(deterministicRandom() * 1024);
    const r = 1 + deterministicRandom() * 2;
    const shade = Math.floor(40 + deterministicRandom() * 60);
    ctx.fillStyle = `rgb(${shade},${shade + 2},${shade + 4})`;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 24);
  return tex;
}

function createBrickTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#b93c24';
  ctx.fillRect(0, 0, 512, 512);

  for (let i = 0; i < 25000; i++) {
    const x = Math.floor(deterministicRandom() * 512);
    const y = Math.floor(deterministicRandom() * 512);
    const delta = (deterministicRandom() * 50 - 25);
    const r = Math.max(0, Math.min(255, 185 + delta));
    const g = Math.max(0, Math.min(255, 60 + delta * 0.5));
    const b = Math.max(0, Math.min(255, 36 + delta * 0.3));
    ctx.fillStyle = `rgb(${r},${g},${b})`;
    ctx.fillRect(x, y, 1 + deterministicRandom() * 2, 1 + deterministicRandom() * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  return tex;
}

