function emitSparks(pos, count = 35) {
  for (let i = 0; i < count; i++) {
    const mesh = new THREE.Mesh(sparkGeo, sparkMat);
    mesh.position.copy(pos);
    scene.add(mesh);
    sparkParticles.push({
      mesh,
      vel: new THREE.Vector3(
        (deterministicRandom() - 0.3) * 12.0,
        2.0 + deterministicRandom() * 8.0,
        (deterministicRandom() - 0.5) * 10.0
      ),
      life: 1.0,
      maxLife: 0.3 + deterministicRandom() * 0.4
    });
  }
}

function updateParticles(dt) {
  // Dust
  for (let i = dustParticles.length - 1; i >= 0; i--) {
    const p = dustParticles[i];
    p.life -= dt / p.maxLife;
    if (p.life <= 0) {
      scene.remove(p.mesh);
      dustParticles.splice(i, 1);
      continue;
    }
    p.mesh.position.addScaledVector(p.vel, dt);
    p.mesh.scale.multiplyScalar(1 + dt * 0.8);
    p.mesh.material.opacity = p.life * 0.3;
  }

  // Sparks
  for (let i = sparkParticles.length - 1; i >= 0; i--) {
    const p = sparkParticles[i];
    p.life -= dt / p.maxLife;
    if (p.life <= 0) {
      scene.remove(p.mesh);
      sparkParticles.splice(i, 1);
      continue;
    }
    p.vel.y -= 9.81 * dt;
    p.mesh.position.addScaledVector(p.vel, dt);
    if (p.mesh.position.y < 0.03) {
      p.mesh.position.y = 0.03;
      p.vel.y = -p.vel.y * 0.4;
      p.vel.x *= 0.7;
      p.vel.z *= 0.7;
    }
  }
}

