class BreakableConstraint {
  constructor(constraint, bodyA, bodyB, thresholdImpulse, onBreak) {
    this.constraint = constraint;
    this.bodyA = bodyA;
    this.bodyB = bodyB;
    this.threshold = thresholdImpulse;
    this.onBreak = onBreak;
    this.broken = false;
  }

  checkBreak(impulse) {
    if (this.broken) return false;
    if (impulse >= this.threshold) {
      this.broken = true;
      world.removeConstraint(this.constraint);
      if (this.onBreak) this.onBreak();
      return true;
    }
    return false;
  }
}

function initPhysicsWorld() {
  world = new CANNON.World();
  world.gravity.set(0, -params.gravity, 0);
  world.solver.iterations = 25;
  world.solver.tolerance = 0.0001;
  world.allowSleep = true;

  // Contact Materials
  groundMatCannon = new CANNON.Material('ground');
  brickMatCannon = new CANNON.Material('brick');

  carMatCannon = new CANNON.Material('car');

  // Brick on Ground
  world.addContactMaterial(new CANNON.ContactMaterial(brickMatCannon, groundMatCannon, {
    friction: params.brickFriction,
    restitution: params.brickRestitution
  }));

  // Brick on Brick
  world.addContactMaterial(new CANNON.ContactMaterial(brickMatCannon, brickMatCannon, {
    friction: params.brickFriction,
    restitution: params.brickRestitution
  }));

  // Car on Brick
  world.addContactMaterial(new CANNON.ContactMaterial(carMatCannon, brickMatCannon, {
    friction: 0.55,
    restitution: 0.15
  }));

  // Car on Ground
  world.addContactMaterial(new CANNON.ContactMaterial(carMatCannon, groundMatCannon, {
    friction: params.groundFriction,
    restitution: 0.10
  }));

  // Physical ground plane
  const groundBody = new CANNON.Body({ mass: 0, material: groundMatCannon });
  groundBody.addShape(new CANNON.Plane());
  groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
  world.addBody(groundBody);
}

/* =========================================================================
   BRICK WALL BUILDER
   Freestanding brick wall, staggered running bond, 2 layers, individual rigid bodies.
   ========================================================================= */
function buildBrickWall() {
  const wallX = 10.0; // Near far end of track
  const cols = params.wallCols;
  const rows = params.wallRows;
  const layers = params.wallDepth;
  const bw = params.brickW;
  const bh = params.brickH;
  const bd = params.brickD;
  const mass = params.brickMass;

  const brickBoxGeo = new THREE.BoxGeometry(bd - 0.006, bh - 0.006, bw - 0.006);

  for (let r = 0; r < rows; r++) {
    const y = bh / 2 + r * bh;
    const isOddRow = (r % 2 === 1);
    const staggerZ = isOddRow ? (bw * 0.25) : 0;

    for (let c = 0; c < cols; c++) {
      const z = (c - (cols - 1) / 2) * bw + staggerZ;

      for (let l = 0; l < layers; l++) {
        const x = wallX + (l - (layers - 1) / 2) * bd;

        // Cannon Rigid Body
        const body = new CANNON.Body({
          mass: mass,
          material: brickMatCannon,
          shape: new CANNON.Box(new CANNON.Vec3(bd / 2 - 0.003, bh / 2 - 0.003, bw / 2 - 0.003)),
          position: new CANNON.Vec3(x, y, z),
          linearDamping: 0.08,
          angularDamping: 0.08
        });
        body.sleepSpeedLimit = 0.15;
        body.sleepTimeLimit = 0.5;
        body.isBrick = true;
        world.addBody(body);
        brickBodies.push(body);

        // Three.js Mesh with realistic color variation
        const colorVariation = (deterministicRandom() * 0.2 - 0.1);
        const rCol = THREE.MathUtils.clamp(0.72 + colorVariation, 0.5, 0.9);
        const gCol = THREE.MathUtils.clamp(0.24 + colorVariation * 0.5, 0.15, 0.4);
        const bCol = THREE.MathUtils.clamp(0.15 + colorVariation * 0.3, 0.08, 0.3);

        const brickMeshMat = new THREE.MeshStandardMaterial({
          map: brickTex,
          color: new THREE.Color(rCol, gCol, bCol),
          roughness: 0.9,
          metalness: 0.05
        });

        const mesh = new THREE.Mesh(brickBoxGeo, brickMeshMat);
        mesh.position.set(x, y, z);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        scene.add(mesh);
        brickMeshes.push(mesh);
      }
    }
  }
}

