// 8. FOUR WHEELS WITH VISIBLE RIMS & TIRES
function createWheel(name, mass, relX, relZ, isFront) {
  const wMass = mass * massRatio;
  const radius = 0.35;
  const width = 0.24;

  const body = new CANNON.Body({
    mass: wMass,
    material: carMatCannon,
    shape: new CANNON.Cylinder(radius, radius, width, 16),
    position: new CANNON.Vec3(startX + relX, radius + 0.02, relZ),
    linearDamping: 0.03,
    angularDamping: 0.04
  });
  body.partName = name;
  body.isWheel = true;
  // Align cylinder axis to Z
  body.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), Math.PI / 2);
  world.addBody(body);
  carPartBodies.push(body);

  // Visual Wheel Group
  const group = new THREE.Group();
  // Rubber Tire
  const tireMesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, width, 24), wheelRubberMat);
  tireMesh.rotation.x = Math.PI / 2;
  tireMesh.castShadow = true;
  group.add(tireMesh);

  // Alloy Rim
  const rimMesh = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.72, radius * 0.72, width + 0.01, 16), wheelAlloyMat);
  rimMesh.rotation.x = Math.PI / 2;
  group.add(rimMesh);

  // 5 Spokes
  const spokeGeo = new THREE.BoxGeometry(radius * 1.3, 0.04, width + 0.015);
  for (let s = 0; s < 5; s++) {
    const spoke = new THREE.Mesh(spokeGeo, wheelAlloyMat);
    spoke.rotation.z = s * (Math.PI / 2.5);
    group.add(spoke);
  }

  // Brake rotor and caliper
  const rotor = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.55, radius * 0.55, 0.02, 16), brakeRotorMat);
  rotor.rotation.x = Math.PI / 2;
  rotor.position.z = relZ > 0 ? -0.06 : 0.06;
  group.add(rotor);

  const caliper = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.14, 0.06), brakeCaliperMat);
  caliper.position.set(0, radius * 0.42, relZ > 0 ? -0.06 : 0.06);
  group.add(caliper);

  scene.add(group);
  carPartMeshes.push({ body, mesh: group, isWheel: true });

  // Wheel constraint to Front Clip or Cabin
  const targetHost = isFront ? frontClipBody : cabinBody;
  const threshold = isFront ? 1400 : 2800; // Front wheels snap off during violent crash
  const cWheel = new CANNON.LockConstraint(targetHost, body);
  world.addConstraint(cWheel);
  breakableConstraints.push(new BreakableConstraint(cWheel, targetHost, body, threshold, () => {
    body.velocity.x += (deterministicRandom() * 4 - 2);
    body.velocity.y += 2.0;
    body.angularVelocity.z += (deterministicRandom() * 15 - 7.5);
  }));

  return body;
}

wheelFLBody = createWheel('Wheel Front-Left', 26, 1.45, 0.88, true);
wheelFRBody = createWheel('Wheel Front-Right', 26, 1.45, -0.88, true);
wheelRLBody = createWheel('Wheel Rear-Left', 26, -0.80, 0.88, false);
wheelRRBody = createWheel('Wheel Rear-Right', 26, -0.80, -0.88, false);

// 9. SHATTERABLE GLASS SHARDS (Created on impact)
function spawnGlassShards(originPos) {
  if (intactWindshieldMesh) intactWindshieldMesh.visible = false;
  sound.playGlassShatter();

  const shardGeo = new THREE.BoxGeometry(0.24, 0.02, 0.32);
  for (let i = 0; i < 8; i++) {
    const sx = originPos.x + 0.4 + (i % 2) * 0.3;
    const sy = originPos.y + 0.3 + (Math.floor(i / 2) * 0.12);
    const sz = (i - 3.5) * 0.22;

    const sBody = new CANNON.Body({
      mass: 2.5,
      material: carMatCannon,
      shape: new CANNON.Box(new CANNON.Vec3(0.12, 0.01, 0.16)),
      position: new CANNON.Vec3(sx, sy, sz),
      linearDamping: 0.08,
      angularDamping: 0.08
    });

    // Forward blast velocity
    sBody.velocity.set(
      currentCarSpeed * 0.75 + (deterministicRandom() * 4 - 2),
      1.5 + deterministicRandom() * 3.0,
      (deterministicRandom() - 0.5) * 6.0
    );
    sBody.angularVelocity.set(
      (deterministicRandom() - 0.5) * 20,
      (deterministicRandom() - 0.5) * 20,
      (deterministicRandom() - 0.5) * 20
    );
    world.addBody(sBody);
    glassShardBodies.push(sBody);

      const sMesh = new THREE.Mesh(shardGeo, glassMaterial);
      sMesh.castShadow = true;
      scene.add(sMesh);
      glassShardMeshes.push({ body: sBody, mesh: sMesh });
    }
  }

  // Attach collision listener to detect constraint breaks & sparks
  for (const b of carPartBodies) {
    b.addEventListener('collide', (e) => {
      const relV = Math.abs(e.contact.getImpactVelocityAlongNormal());
      const other = e.contact.bi === b ? e.contact.bj : e.contact.bi;
      const m1 = b.mass > 0 ? b.mass : 1000;
      const m2 = other.mass > 0 ? other.mass : 1000;
      const impulse = relV * ((m1 * m2) / (m1 + m2));

      // Check breakable constraints
      for (let i = 0; i < breakableConstraints.length; i++) {
        const bc = breakableConstraints[i];
        if (!bc.broken && (bc.bodyA === b || bc.bodyB === b)) {
          bc.checkBreak(impulse);
        }
      }

      // Trigger impact sequence once on high collision impulse
      if (!crashOccurred && impulse > 250) {
        crashOccurred = true;
        crashImpactTime = simulationTime;
        sound.playImpact(Math.min(1.5, impulse / 800));
        emitDust(frontClipBody.position, 40);
        emitSparks(frontClipBody.position, 60);
        spawnGlassShards(frontClipBody.position);

        cameraShakeAmp = 0.35;
        cameraShakeDecay = 1.0;

        const gForce = (relV / (1 / 60)) / 9.81;
        peakImpactG = Math.max(peakImpactG, gForce);
      } else if (impulse > 80 && (b === frontClipBody || b === frontBumperBody || b.isWheel)) {
        emitSparks(b.position, 12);
      }
    });
  }
}

/* =========================================================================
   EXPERIMENT CONTROLLER & RESET/REPLAY LOGIC
   ========================================================================= */
function resetSimulation() {
  resetRandom(42);
  simulationTime = 0;
  crashOccurred = false;
  crashImpactTime = 0;
  peakImpactG = 0;
  currentCarSpeed = 0;
  cameraShakeAmp = 0;

  // Clean existing brick objects
  for (const m of brickMeshes) scene.remove(m);
  brickMeshes = [];
  brickBodies = [];

  // Clean car objects
  for (const item of carPartMeshes) scene.remove(item.mesh);
  carPartMeshes = [];
  carPartBodies = [];
  breakableConstraints = [];

  // Clean shards
  for (const item of glassShardMeshes) scene.remove(item.mesh);
  glassShardBodies = [];
  glassShardMeshes = [];

  // Clean dust & sparks
  for (const p of dustParticles) scene.remove(p.mesh);
  dustParticles.length = 0;
  for (const p of sparkParticles) scene.remove(p.mesh);
  sparkParticles.length = 0;

  // Recreate Physics World and elements
  initPhysicsWorld();
  buildBrickWall();
  buildCarAssembly();

  initialKE = 0.5 * params.carMass * (params.carSpeed * params.carSpeed) / 1000.0;
  document.getElementById('hudKE').innerHTML = `${initialKE.toFixed(1)}<span class="telemetry-unit">kJ</span>`;
  document.getElementById('hudBricks').innerHTML = `0<span class="telemetry-unit">/ ${brickBodies.length}</span>`;
  document.getElementById('hudParts').innerHTML = `0<span class="telemetry-unit">/ ${carPartBodies.length}</span>`;
  updateStatusBadge('ACCELERATING', '#10b981');

  sound.init();
}

function updateStatusBadge(text, color) {
  const badge = document.getElementById('simStatusBadge');
  const label = document.getElementById('simStatusText');
  label.innerText = text;
  badge.style.color = color;
}

/* =========================================================================
   FIXED TIMESTEP PHYSICS LOOP & SUBSTEPPING
   ========================================================================= */
const PHYSICS_DT = 1 / 120; // 120 Hz fixed substepping
let lastFrameTime = performance.now();
let physicsAccumulator = 0;
let timeScale = 1.0;

function stepPhysics(deltaSec) {
  physicsAccumulator += Math.min(deltaSec, 0.1) * timeScale;

  while (physicsAccumulator >= PHYSICS_DT) {
    simulationTime += PHYSICS_DT;

    // Drive Phase (before crash impact)
    if (!crashOccurred) {
      // Accelerate smoothly to mandatory target speed
      const accel = 12.0; // m/s2
      currentCarSpeed = Math.min(params.carSpeed, accel * simulationTime);

      // Update audio pitch
      sound.updateEngine(currentCarSpeed, params.carSpeed);

      // Move assembled car forward in locked formation
      for (const body of carPartBodies) {
        body.velocity.set(currentCarSpeed, 0, 0);
      }

      // Spin wheels visibly
      const wheelOmega = currentCarSpeed / 0.35;
      if (wheelFLBody) wheelFLBody.angularVelocity.set(0, 0, -wheelOmega);
      if (wheelFRBody) wheelFRBody.angularVelocity.set(0, 0, -wheelOmega);
      if (wheelRLBody) wheelRLBody.angularVelocity.set(0, 0, -wheelOmega);
      if (wheelRRBody) wheelRRBody.angularVelocity.set(0, 0, -wheelOmega);
    } else {
      // After impact: calculate speed from cabin velocity
      if (cabinBody) {
        currentCarSpeed = cabinBody.velocity.length();
      }
    }

    // Step Cannon-es rigid bodies
    world.step(PHYSICS_DT);

    physicsAccumulator -= PHYSICS_DT;
  }

  // Sync Three.js meshes with Cannon rigid bodies
  for (let i = 0; i < brickBodies.length; i++) {

    brickMeshes[i].position.copy(brickBodies[i].position);
    brickMeshes[i].quaternion.copy(brickBodies[i].quaternion);
  }

  for (let i = 0; i < carPartMeshes.length; i++) {
    const item = carPartMeshes[i];
    item.mesh.position.copy(item.body.position);
    item.mesh.quaternion.copy(item.body.quaternion);
  }

  for (let i = 0; i < glassShardMeshes.length; i++) {
    const item = glassShardMeshes[i];
    item.mesh.position.copy(item.body.position);
    item.mesh.quaternion.copy(item.body.quaternion);
  }

  updateParticles(deltaSec * timeScale);
  updateTelemetry();
}

/* =========================================================================
   TELEMETRY & HUD UPDATE
   ========================================================================= */
function updateTelemetry() {
  // Speed
  document.getElementById('hudSpeed').innerHTML = `${currentCarSpeed.toFixed(1)}<span class="telemetry-unit">m/s</span>`;
  document.getElementById('hudKmh').innerHTML = `${Math.round(currentCarSpeed * 3.6)}<span class="telemetry-unit">km/h</span>`;

  // Current Kinetic Energy
  const currentKE = 0.5 * params.carMass * (currentCarSpeed * currentCarSpeed) / 1000.0;
  document.getElementById('hudKE').innerHTML = `${Math.max(0, currentKE).toFixed(1)}<span class="telemetry-unit">kJ</span>`;

  // Peak G-Force
  document.getElementById('hudPeakG').innerHTML = `${peakImpactG.toFixed(1)}<span class="telemetry-unit">G</span>`;

  // Displaced Bricks Count
  let displacedBricks = 0;
  for (const b of brickBodies) {
    if (b.position.x > 10.3 || b.velocity.length() > 0.4) displacedBricks++;
  }
  document.getElementById('hudBricks').innerHTML = `${displacedBricks}<span class="telemetry-unit">/ ${brickBodies.length}</span>`;

  // Detached Parts Count
  const brokenCount = breakableConstraints.filter(bc => bc.broken).length;
  document.getElementById('hudParts').innerHTML = `${brokenCount}<span class="telemetry-unit">/ ${breakableConstraints.length}</span>`;

  // Simulation Status state
  if (!crashOccurred) {
    updateStatusBadge('ACCELERATING', '#10b981');
  } else if (simulationTime - crashImpactTime < 1.2) {
    updateStatusBadge('IMPACT COLLISION', '#ef4444');
  } else if (currentCarSpeed > 0.4) {
    updateStatusBadge('DEBRIS SCATTERING', '#f59e0b');
  } else {
    updateStatusBadge('WRECK SETTLED', '#06b6d4');
  }
}

/* =========================================================================
   CINEMATIC CAMERA CHOREOGRAPHY
   ========================================================================= */
function updateCamera(dt) {
  if (!cabinBody) return;

  // Screen Shake
  let shakeX = 0, shakeY = 0;
  if (cameraShakeAmp > 0.001) {
    shakeX = (Math.sin(simulationTime * 55) * cameraShakeAmp);
    shakeY = (Math.cos(simulationTime * 45) * cameraShakeAmp);
    cameraShakeAmp *= Math.max(0, 1.0 - dt * 2.8);
  }

  if (cameraMode === 'cinematic') {
    controls.enabled = false;
    if (!crashOccurred) {
      // Approach tracking shot: keeps car and far wall framed
      const targetCamX = cabinBody.position.x + 3.8;
      camera.position.x = THREE.MathUtils.lerp(camera.position.x, targetCamX, 0.08) + shakeX;
      camera.position.y = 3.6 + shakeY;
      camera.position.z = 8.8;
      camera.lookAt(cabinBody.position.x + 5.5, 1.1, 0);
    } else {
      // Impact vantage hold & slow drift
      const elapsed = simulationTime - crashImpactTime;
      const orbitAngle = Math.min(0.6, elapsed * 0.12);
      const camRadius = 10.5;

      const cx = 10.0 + Math.sin(orbitAngle) * camRadius + shakeX;
      const cz = Math.cos(orbitAngle) * camRadius;
      camera.position.x = THREE.MathUtils.lerp(camera.position.x, cx, 0.04);
      camera.position.y = THREE.MathUtils.lerp(camera.position.y, 3.8 + shakeY, 0.05);
      camera.position.z = THREE.MathUtils.lerp(camera.position.z, cz, 0.04);
      camera.lookAt(10.5, 0.8, 0);
    }
  } else if (cameraMode === 'trackside') {
    controls.enabled = false;
    // Low angle crash-test camera positioned near the wall
    camera.position.set(11.5 + shakeX, 1.2 + shakeY, 4.5);
    camera.lookAt(cabinBody.position.x, 0.7, 0);
  } else if (cameraMode === 'chase') {
    controls.enabled = false;
    // Chase cam behind car
    camera.position.set(cabinBody.position.x - 6.5 + shakeX, 2.8 + shakeY, cabinBody.position.z);
    camera.lookAt(cabinBody.position.x + 4.0, 1.0, cabinBody.position.z);
  } else if (cameraMode === 'orbit') {
    controls.enabled = true;
    controls.target.copy(cabinBody.position);
    controls.update();
  }
}

/* =========================================================================
   ANIMATION RENDER LOOP
   ========================================================================= */
function animate(now) {
  requestAnimationFrame(animate);
  const deltaSec = (now - lastFrameTime) / 1000.0;
  lastFrameTime = now;

  stepPhysics(deltaSec);
  updateCamera(deltaSec);

  renderer.render(scene, camera);
}

