const CANNON = require('/tmp/cannon-es.cjs');
const world = new CANNON.World();
const chassis = new CANNON.Body({ mass: 600, shape: new CANNON.Box(new CANNON.Vec3(1, 0.4, 0.8)) });
chassis.position.set(0, 0.6, 0);
const wheel = new CANNON.Body({ mass: 25, shape: new CANNON.Sphere(0.35) });
wheel.position.set(1.4, 0.35, 0.8);
world.addBody(chassis);
world.addBody(wheel);

const pivotA = new CANNON.Vec3(1.4, -0.25, 0.8);
const pivotB = new CANNON.Vec3(0, 0, 0);
const c = new CANNON.PointToPointConstraint(chassis, pivotA, wheel, pivotB);
world.addConstraint(c);
console.log('Wheel equations:', c.equations.length); // 3 equations!
world.step(1/60);
console.log('Step ok, wheel pos:', wheel.position);
"

