node -e "
const CANNON = require('/tmp/cannon-es.cjs');

const world = new CANNON.World();
world.broadphase = new CANNON.SAPBroadphase(world);
world.gravity.set(0, -9.81, 0);

const groundMat = new CANNON.Material('ground');
const brickMat = new CANNON.Material('brick');
const carMat = new CANNON.Material('car');

world.addContactMaterial(new CANNON.ContactMaterial(brickMat, groundMat, { friction: 0.72, restitution: 0.18 }));
world.addContactMaterial(new CANNON.ContactMaterial(brickMat, brickMat, { friction: 0.72, restitution: 0.18 }));
world.addContactMaterial(new CANNON.ContactMaterial(carMat, brickMat, { friction: 0.55, restitution: 0.15 }));
world.addContactMaterial(new CANNON.ContactMaterial(carMat, groundMat, { friction: 0.85, restitution: 0.10 }));

const groundBody = new CANNON.Body({ mass: 0, material: groundMat });
groundBody.addShape(new CANNON.Plane());
groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
world.addBody(groundBody);

const bw = 0.5, bh = 0.24, bd = 0.2;
const bricks = [];
for (let r = 0; r < 8; r++) {
  const y = bh / 2 + r * bh;
  for (let c = 0; c < 12; c++) {
    const offsetZ = (r % 2 === 1) ? (bw * 0.25) : 0;
    const z = (c - 5.5) * bw + offsetZ;
    for (let l = 0; l < 2; l++) {
      const x = 10 + (l - 0.5) * bd;
      const b = new CANNON.Body({
        mass: 2.5,
        material: brickMat,
        shape: new CANNON.Box(new CANNON.Vec3(bd / 2 - 0.003, bh / 2 - 0.003, bw / 2 - 0.003)),
        position: new CANNON.Vec3(x, y, z)
      });
      world.addBody(b);
      bricks.push(b);
    }
  }
}

const startX = 2.0;
const cabin = new CANNON.Body({
  mass: 620,
  material: carMat,
  shape: new CANNON.Box(new CANNON.Vec3(1.10, 0.38, 0.85)),
  position: new CANNON.Vec3(startX, 0.65, 0),
  velocity: new CANNON.Vec3(22, 0, 0)
});
world.addBody(cabin);

const frontClip = new CANNON.Body({
  mass: 250,
  material: carMat,
  shape: new CANNON.Box(new CANNON.Vec3(0.60, 0.32, 0.78)),
  position: new CANNON.Vec3(startX + 1.62, 0.55, 0),
  velocity: new CANNON.Vec3(22, 0, 0)
});
world.addBody(frontClip);

let c = new CANNON.LockConstraint(cabin, frontClip);
world.addConstraint(c);

for (let f = 0; f < 30; f++) {
  world.step(1/60);
}
console.log('After 30 steps:');
console.log('Front clip X:', frontClip.position.x.toFixed(2), 'vel:', frontClip.velocity.x.toFixed(2));
let disp = 0;
for (const b of bricks) {
  if (b.position.x > 10.3 || Math.abs(b.velocity.x) > 0.5) disp++;
}
console.log('Displaced bricks:', disp);
"

