args.command:
node -e "
const fs = require('fs');
const content = fs.readFileSync('index.html', 'utf8');
const scriptMatches = content.match(/<script type=\"module\">([\s\S]*?)<\/script>/);
if (scriptMatches) {
  const code = scriptMatches[1];
  const sanitized = code.replace(/import\s+.*?;/g, '// import');
  try {
    new Function(sanitized);
    console.log('Script syntax verified: OK!');
  } catch (err) {
    console.error('Syntax error:', err);
    process.exit(1);
  }
} else {
  console.error('No script module found');
  process.exit(1);
}
"

